inputs.script:
// Trigger: When Automation Action is not empty
// Input variables:
// - recordId = Airtable record ID from the trigger
// - automationAction = Automation Action from the trigger
// This dispatcher only confirms that n8n accepted the job.
// Completion is tracked through the Lead Lists status fields.

// Inputs are captured by Airtable at trigger time. A downstream workflow may
// clear Automation Action before this script reloads the record, so routing
// must prefer the trigger-time snapshot.
const { recordId, automationAction } = input.config();
const webhookAuth = input.secret("leadListWebhookAuth");
if (!recordId || !String(recordId).startsWith("rec")) {
    throw new Error("A valid Lead Lists record ID is required.");
}

const table = base.getTable("Lead Lists");
const actionField = table.getField("Automation Action");
const processingStatusField = table.getField("Processing Status");
const workflowRunIdField = table.getField("Workflow Run ID");
const processingCompletedAtField = table.getField("Processing Completed At");

const record = await table.selectRecordAsync(recordId, {
    fields: [
        actionField,
        processingStatusField,
        workflowRunIdField,
        processingCompletedAtField,
    ],
});

if (!record) {
    throw new Error(`Lead Lists record ${recordId} no longer exists.`);
}

const triggeredAction = String(automationAction || "").trim();
const currentAction = record.getCellValueAsString(actionField).trim();
const beforeRunId = record.getCellValueAsString(workflowRunIdField).trim();
const beforeProcessingStatus = record
    .getCellValueAsString(processingStatusField)
    .trim()
    .toLowerCase();
const beforeCompletedAt = record
    .getCellValueAsString(processingCompletedAtField)
    .trim();

// A delayed Airtable automation run must never replay the action that caused
// it after the live record has moved to a different action. Conversely, when
// the action has already been cleared (or remains the same) and the record is
// owned by an active workflow run, this trigger is a duplicate acknowledgement
// only: do not POST again. This preserves the original cleared-field race for a
// fresh request (no active run) while preventing duplicate provider work.
if (triggeredAction && currentAction && triggeredAction !== currentAction) {
    throw new Error(
        `SUPERSEDED_AUTOMATION_ACTION: trigger=${triggeredAction}; current=${currentAction}`
    );
}

const action = triggeredAction || currentAction;

const companyAndContactActions = new Set([
    "Generate Filters",
    "Run Company Sample",
    "Review Saved Company Sample",
    "Apply Verified Company Evidence",
    "Test Saved Company Evidence (1)",
    "Refine Company Sample",
    "Expand Companies",
    "Build Contact Sample",
    "Expand Contacts",
    "Apply Contact Decisions",
]);

const verificationActions = new Set([
    "Verify and Finalize",
    "Retry Failed Stage",
]);

const supportedAction =
    action === "Restart Companies" ||
    companyAndContactActions.has(action) ||
    verificationActions.has(action);

if (!supportedAction) {
    throw new Error(
        `Unsupported Automation Action: ${action || "blank"}. ` +
        "Check the Lead Lists action options and router mapping."
    );
}

const duplicateActiveDispatch =
    Boolean(triggeredAction) &&
    Boolean(beforeRunId) &&
    ["running", "processing"].includes(beforeProcessingStatus) &&
    (!currentAction || currentAction === triggeredAction);

if (duplicateActiveDispatch) {
    output.set("started", true);
    output.set("recordId", recordId);
    output.set("action", action);
    output.set("workflow", "Existing active run");
    output.set("webhookUrl", "");
    output.set("n8nResponse", {
        accepted: true,
        asynchronous: true,
        duplicateSuppressed: true,
        processingStatus: beforeProcessingStatus,
        workflowRunId: beforeRunId,
        message: "An active run already owns this action; no duplicate webhook was sent.",
    });
    return;
}

let webhookUrl;
let workflow;

if (action === "Restart Companies") {
    webhookUrl = "https://n8n.dulcy.io/webhook/REDACTED_PATH";
    workflow = "Company Restart";
} else if (companyAndContactActions.has(action)) {
    webhookUrl = "https://n8n.dulcy.io/webhook/REDACTED_PATH";
    workflow = "Company and Contact Review";
} else if (verificationActions.has(action)) {
    webhookUrl = "https://n8n.dulcy.io/webhook/REDACTED_PATH";
    workflow = "Verification Submit and Check";
} else {
    throw new Error(
        `Unsupported Automation Action: ${action || "blank"}. ` +
        "Check the Lead Lists action options and router mapping."
    );
}

const response = await fetch(webhookUrl, {
    method: "POST",
    headers: {
        "Content-Type": "application/json",
        ...(companyAndContactActions.has(action)
            ? { "X-Dulcy-Lead-List-Auth": webhookAuth }
            : {}),
    },
    body: JSON.stringify({ recordId, action }),
});

const responseText = await response.text();
const isN8nRequestTimeout =
    response.status === 408 &&
    /REQUEST_TIMEOUT|Request Timeout/i.test(responseText);

let timeoutAccepted = false;
let observedProcessingStatus = "";
let observedRunId = "";
let observedCompletedAt = "";

if (isN8nRequestTimeout) {
    const refreshedRecord = await table.selectRecordAsync(recordId, {
        fields: [
            processingStatusField,
            workflowRunIdField,
            processingCompletedAtField,
        ],
    });

    observedProcessingStatus = refreshedRecord
        ?.getCellValueAsString(processingStatusField)
        .trim()
        .toLowerCase() || "";
    observedRunId = refreshedRecord
        ?.getCellValueAsString(workflowRunIdField)
        .trim() || "";
    observedCompletedAt = refreshedRecord
        ?.getCellValueAsString(processingCompletedAtField)
        .trim() || "";

    const observedNewRun =
        Boolean(observedRunId) && observedRunId !== beforeRunId;
    const observedNewCompletion =
        Boolean(observedCompletedAt) &&
        observedCompletedAt !== beforeCompletedAt;
    // Airtable's fetch proxy terminates requests at roughly 30 seconds and
    // returns this exact 408 even when n8n continues successfully. Do not
    // retry: a retry could duplicate provider work. Treat only this exact
    // proxy timeout as an asynchronous dispatch acknowledgement. The Lead
    // Lists processing fields remain authoritative for downstream success or
    // failure; the observations below are diagnostic evidence, not a gate.
    timeoutAccepted = true;
}

if (!response.ok && !timeoutAccepted) {
    throw new Error(
        `${workflow} rejected the request with HTTP ${response.status}: ` +
        `${responseText || "No response body"}`
    );
}

let n8nResponse;
if (timeoutAccepted) {
    n8nResponse = {
        accepted: true,
        asynchronous: true,
        httpStatus: response.status,
        processingStatus: observedProcessingStatus,
        workflowRunId: observedRunId,
        completedAt: observedCompletedAt,
        confirmationEvidence:
            observedRunId !== beforeRunId
                ? "new_run"
                : observedCompletedAt !== beforeCompletedAt
                  ? "new_completion"
                  : "pending_status_update",
        message:
            "Airtable timed out waiting for the synchronous response. The request is not retried; Lead List processing fields track the eventual result.",
    };
} else {
    try {
        n8nResponse = responseText
            ? JSON.parse(responseText)
            : { accepted: true };
    } catch {
        n8nResponse = { accepted: true, raw: responseText };
    }
}

output.set("started", true);
output.set("recordId", recordId);
output.set("action", action);
output.set("workflow", workflow);
output.set("webhookUrl", webhookUrl);
output.set("n8nResponse", n8nResponse);
